T=np.load("T.npy")
def clusters(M,thr):
    # greedy compatible clustering of rows of M with -1 wildcards
    n=M.shape[0]; groups=[]
    for i in range(n):
        placed=False
        for g in groups:
            rep=g['rep']; m=(rep>=0)&(M[i]>=0)
            if m.sum()>0 and (rep[m]==M[i][m]).mean()>=thr:
                g['ids'].append(i); r=rep.copy(); r[(r<0)&(M[i]>=0)]=M[i][(r<0)&(M[i]>=0)]; g['rep']=r; placed=True; break
        if not placed: groups.append({'ids':[i],'rep':M[i].copy()})
    return groups
for s in range(4):
