        gr=clusters(T[s],thr); gc=clusters(T[s].T,thr)
        print("skill",s,"thr",thr,"row groups",len(gr),"col groups",len(gc))
    print(" rows",[g['ids'] for g in clusters(T[s],0.75)])
    print(" cols",[g['ids'] for g in clusters(T[s].T,0.75)])
