code = r'''
def rowcorr(M):
    n=32; C=np.zeros((n,n))
    for i in range(n):
        for j in range(n):
            m=(M[i]>=0)&(M[j]>=0)
            if m.sum()>=5 and M[i][m].std()>0 and M[j][m].std()>0: C[i,j]=np.corrcoef(M[i][m],M[j][m])[0,1]
    np.fill_diagonal(C,1.0); return C
def impute(M,beta,p=4):
    C=np.clip(rowcorr(M),0,1)**p; O=(M>=0).astype(float); V=np.where(M>=0,M,0).astype(float); Out=M.astype(float).copy()
    for a in range(32):
        r=C[a]; D=np.zeros((32,32))
        for b in range(32):
            both=O[:,[b]]*O; diff=np.abs(V[:,[b]]-V)*both
            num=(r[:,None]*diff).sum(0); den=(r[:,None]*both).sum(0)
            D[b]=np.where(den>0.5,num/np.maximum(den,1e-9),9.0)
        W=np.exp(-beta*D)*O[a][None,:]; np.fill_diagonal(W,0)
        Est=(W*V[a][None,:]).sum(1)/np.maximum(W.sum(1),1e-9)
        Out[a]=np.where(M[a]>=0,M[a],Est)
    return Out
BETA={0:2.0,1:4.0,2:4.0,3:2.0}
def rowdist(x,y):
    d=x-y; d=d-np.median(d); return float(np.abs(d).mean())
def group_all(F,total=48,minper=8):
    G={s:[{'ids':[a],'rep':F[s][a].copy()} for a in range(32)] for s in range(4)}
    while sum(len(G[s]) for s in G)>total:
        best=None
        for s in G:
            if len(G[s])<=minper: continue
            gs=G[s]
            for i in range(len(gs)):
                for j in range(i+1,len(gs)):
                    ni,nj=len(gs[i]['ids']),len(gs[j]['ids'])
                    c=rowdist(gs[i]['rep'],gs[j]['rep'])*ni*nj/(ni+nj)
                    if best is None or c<best[0]: best=(c,s,i,j)
        _,s,i,j=best; gi,gj=G[s][i],G[s][j]
        sh=np.median(gj['rep']-gi['rep']); ni,nj=len(gi['ids']),len(gj['ids'])
        gi['rep']=(ni*gi['rep']+nj*(gj['rep']-sh))/(ni+nj); gi['ids']+=gj['ids']; del G[s][j]
    return G
def table_from_groups(F,G):
    P=np.zeros((4,32,32)); info={}
    for s in G:
        for gi,g in enumerate(G[s]):
            for a in g['ids']:
                sh=float(np.median(F[s][a]-g['rep'])); P[s,a]=g['rep']+sh; info[(s,a)]=(gi,sh)
    return P,info
'''
